redeem.script:
(async () => {
  try {
    const r = await fetch('/api/v1/auth/oidc/app-session', { method: 'POST', credentials: 'same-origin',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ code: 'abc', code_verifier: 'dBjftJeZ4CVP-mB92K27uhbUJU1p1r_wW1gFWFOEjXk' }) });
    if (r.redirected) { location.replace(r.url); return; }
    let e = 'oidc_failed';
    try { e = (await r.json()).error.code || e; } catch (_) {}
    location.replace('/?error=' + encodeURIComponent(e));
  } catch (_) { location.replace('/?error=oidc_failed'); }
})();
